import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';

export const BASELINE_POLICY_VERSION = 'prisma-baseline-additive-v1';
export const CANONICAL_MIGRATION_LOCK = [
  '# Please do not edit this file manually',
  '# It should be added in your version-control system (i.e. Git)',
  'provider = "postgresql"',
  '',
].join('\n');

export const SHA256_PATTERN = /^[a-f0-9]{64}$/;
export const MIGRATION_DIRECTORY_PATTERN = /^\d{14}_[a-z0-9][a-z0-9_]*$/;
export const BASELINE_DIRECTORY_PATTERN = /^\d{14}_baseline$/;

const PRISMA_TOOLCHAIN_PACKAGES = Object.freeze([
  '@prisma/client',
  '@prisma/debug',
  '@prisma/engines',
  '@prisma/engines-version',
  '@prisma/fetch-engine',
  '@prisma/get-platform',
  'prisma',
]);

const MAX_BASELINE_SQL_BYTES = 5 * 1024 * 1024;
const MAX_BASELINE_STATEMENTS = 2048;
const MAX_BASELINE_STATEMENT_BYTES = 512 * 1024;

export function sha256(value) {
  return crypto.createHash('sha256').update(value).digest('hex');
}

export function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export function hasExactKeys(value, keys) {
  if (!isPlainObject(value)) return false;
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
}

export function inspectRegularFile(filePath, errors, code) {
  if (!fs.existsSync(filePath)) {
    errors.push({ code, message: `Falta ${path.basename(filePath)}.` });
    return false;
  }
  const stat = fs.lstatSync(filePath);
  if (!stat.isFile() || stat.isSymbolicLink()) {
    errors.push({ code, message: `${path.basename(filePath)} debe ser un archivo regular, no un enlace.` });
    return false;
  }
  return true;
}

export function normalizedText(filePath) {
  const bytes = fs.readFileSync(filePath);
  const text = new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  return text.replace(/\r\n?/g, '\n');
}

export function normalizedFileSha256(filePath) {
  return sha256(normalizedText(filePath));
}

export function readCanonicalLfText(filePath, errors, code) {
  if (!inspectRegularFile(filePath, errors, code)) return null;
  let text;
  try {
    text = new TextDecoder('utf-8', { fatal: true }).decode(fs.readFileSync(filePath));
  } catch {
    errors.push({ code, message: `${path.basename(filePath)} debe ser UTF-8 v\u00e1lido.` });
    return null;
  }
  if (text.startsWith('\uFEFF') || text.includes('\0') || text.includes('\r') || !text.endsWith('\n')) {
    errors.push({
      code,
      message: `${path.basename(filePath)} debe usar UTF-8 sin BOM, LF can\u00f3nico, sin NUL y newline final.`,
    });
    return null;
  }
  return text;
}

function safeJson(filePath) {
  return JSON.parse(normalizedText(filePath));
}

function inspectSchemaProvider(schemaPath, errors) {
  let schema;
  try {
    schema = normalizedText(schemaPath);
  } catch {
    errors.push({ code: 'SCHEMA_INVALID_UTF8', message: 'schema.prisma debe ser UTF-8 v\u00e1lido.' });
    return null;
  }
  const datasourceMatches = [...schema.matchAll(/\bdatasource\s+db\s*\{([\s\S]*?)\}/g)];
  const providerMatches = datasourceMatches.length === 1
    ? [...datasourceMatches[0][1].matchAll(/\bprovider\s*=\s*"([^"]+)"/g)]
    : [];
  if (providerMatches.length !== 1 || providerMatches[0][1] !== 'postgresql') {
    errors.push({
      code: 'SCHEMA_PROVIDER_INVALID',
      message: 'schema.prisma debe declarar exactamente datasource db con provider = "postgresql".',
    });
    return null;
  }
  return providerMatches[0][1];
}

function asciiCompare(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function readPackageJson(filePath, errors, code) {
  if (!inspectRegularFile(filePath, errors, code)) return null;
  try {
    return safeJson(filePath);
  } catch {
    errors.push({ code, message: `${path.basename(filePath)} no es JSON UTF-8 v\u00e1lido.` });
    return null;
  }
}

function lockProjection(lock, errors, label) {
  if (!isPlainObject(lock?.packages)) {
    errors.push({ code: 'PRISMA_TOOLCHAIN_INVALID', message: `${label} no contiene packages de lockfile v3.` });
    return null;
  }
  const projection = [];
  for (const packageName of PRISMA_TOOLCHAIN_PACKAGES) {
    const entry = lock.packages[`node_modules/${packageName}`];
    if (!isPlainObject(entry)
      || typeof entry.version !== 'string'
      || typeof entry.resolved !== 'string'
      || typeof entry.integrity !== 'string') {
      errors.push({
        code: 'PRISMA_TOOLCHAIN_INVALID',
        message: `${label} no fija version, origen e integridad para ${packageName}.`,
      });
      return null;
    }
    projection.push({
      package: packageName,
      version: entry.version,
      resolved: entry.resolved,
      integrity: entry.integrity,
    });
  }
  return projection.sort((left, right) => asciiCompare(left.package, right.package));
}

function packagePrismaDeclaration(pkg) {
  return {
    prisma: pkg?.devDependencies?.prisma ?? pkg?.dependencies?.prisma ?? null,
    client: pkg?.dependencies?.['@prisma/client'] ?? pkg?.devDependencies?.['@prisma/client'] ?? null,
  };
}

export function inspectPrismaToolchain(repoRoot, errors) {
  const rootPackagePath = path.join(repoRoot, 'package.json');
  const rootLockPath = path.join(repoRoot, 'package-lock.json');
  const backendPackagePath = path.join(repoRoot, 'backend', 'package.json');
  const backendLockPath = path.join(repoRoot, 'backend', 'package-lock.json');
  const rootPackage = readPackageJson(rootPackagePath, errors, 'PACKAGE_MISSING');
  const rootLock = readPackageJson(rootLockPath, errors, 'PACKAGE_LOCK_MISSING');
  const backendPackage = readPackageJson(backendPackagePath, errors, 'BACKEND_PACKAGE_MISSING');
  const backendLock = readPackageJson(backendLockPath, errors, 'BACKEND_PACKAGE_LOCK_MISSING');
  if (!rootPackage || !rootLock || !backendPackage || !backendLock) return null;

  const rootProjection = lockProjection(rootLock, errors, 'package-lock.json');
  const backendProjection = lockProjection(backendLock, errors, 'backend/package-lock.json');
  if (!rootProjection || !backendProjection) return null;
  if (JSON.stringify(rootProjection) !== JSON.stringify(backendProjection)) {
    errors.push({
      code: 'PRISMA_TOOLCHAIN_DIVERGENT',
      message: 'Los lockfiles root y backend no fijan el mismo toolchain Prisma.',
    });
    return null;
  }

  const prismaEntry = rootProjection.find(item => item.package === 'prisma');
  const clientEntry = rootProjection.find(item => item.package === '@prisma/client');
  const enginesEntry = rootProjection.find(item => item.package === '@prisma/engines');
  const engineVersionEntry = rootProjection.find(item => item.package === '@prisma/engines-version');
  const prismaVersion = prismaEntry?.version;
  const declarations = [packagePrismaDeclaration(rootPackage), packagePrismaDeclaration(backendPackage)];
  if (!/^\d+\.\d+\.\d+$/.test(String(prismaVersion || ''))
    || clientEntry?.version !== prismaVersion
    || enginesEntry?.version !== prismaVersion
    || declarations.some(item => item.prisma !== prismaVersion || item.client !== prismaVersion)) {
    errors.push({
      code: 'PRISMA_TOOLCHAIN_VERSION_INVALID',
      message: 'Prisma CLI, Client, engines y declaraciones deben usar la misma versi\u00f3n exacta.',
    });
    return null;
  }
  const prismaEngineVersion = engineVersionEntry?.version;
  if (!new RegExp(`^${prismaVersion.replaceAll('.', '\\.')}\\-\\d+\\.[a-f0-9]{40}$`).test(String(prismaEngineVersion || ''))) {
    errors.push({
      code: 'PRISMA_ENGINE_VERSION_INVALID',
      message: 'El engine Prisma no tiene una versi\u00f3n exacta y un commit de 40 hexadecimales.',
    });
    return null;
  }

  const prismaToolchainLockSha256 = sha256(JSON.stringify({
    root: rootProjection,
    backend: backendProjection,
  }));
  return {
    prismaMajor: Number(prismaVersion.split('.')[0]),
    prismaVersion,
    prismaEngineVersion,
    prismaToolchainLockSha256,
  };
}

function lexSqlStatements(sql) {
  const statements = [];
  let current = '';
  let index = 0;
  let blockDepth = 0;
  let state = 'normal';
  let dollarDelimiter = null;

  const appendPlaceholder = value => {
    if (!current.endsWith(' ')) current += ' ';
    current += value;
    current += ' ';
  };

  while (index < sql.length) {
    const char = sql[index];
    const next = sql[index + 1];
    if (state === 'line-comment') {
      if (char === '\n') {
        current += ' ';
        state = 'normal';
      }
      index += 1;
      continue;
    }
    if (state === 'block-comment') {
      if (char === '/' && next === '*') {
        blockDepth += 1;
        index += 2;
      } else if (char === '*' && next === '/') {
        blockDepth -= 1;
        index += 2;
        if (blockDepth === 0) {
          current += ' ';
          state = 'normal';
        }
      } else {
        index += 1;
      }
      continue;
    }
    if (state === 'single-quote') {
      if (char === "'" && next === "'") {
        index += 2;
      } else if (char === "'") {
        index += 1;
        state = 'normal';
      } else {
        index += 1;
      }
      continue;
    }
    if (state === 'double-quote') {
      if (char === '"' && next === '"') {
        index += 2;
      } else if (char === '"') {
        index += 1;
        state = 'normal';
      } else {
        index += 1;
      }
      continue;
    }
    if (state === 'dollar-quote') {
      if (sql.startsWith(dollarDelimiter, index)) {
        index += dollarDelimiter.length;
        dollarDelimiter = null;
        state = 'normal';
      } else {
        index += 1;
      }
      continue;
    }

    if (char === '-' && next === '-') {
      state = 'line-comment';
      index += 2;
      continue;
    }
    if (char === '/' && next === '*') {
      state = 'block-comment';
      blockDepth = 1;
      index += 2;
      continue;
    }
    if (char === "'") {
      appendPlaceholder('S');
      state = 'single-quote';
      index += 1;
      continue;
    }
    if (char === '"') {
      appendPlaceholder('I');
      state = 'double-quote';
      index += 1;
      continue;
    }
    if (char === '$') {
      const match = sql.slice(index).match(/^\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$/);
      if (match) {
        appendPlaceholder('S');
        dollarDelimiter = match[0];
        state = 'dollar-quote';
        index += dollarDelimiter.length;
        continue;
      }
    }
    if (char === ';') {
      const statement = current.replace(/\s+/g, ' ').trim();
      if (statement) statements.push(statement);
      current = '';
      index += 1;
      continue;
    }
    current += char;
    index += 1;
  }

  if (state !== 'normal' && state !== 'line-comment') {
    return { statements: [], error: 'SQL_UNTERMINATED_LEXEME' };
  }
  const trailing = current.replace(/\s+/g, ' ').trim();
  if (trailing) statements.push(trailing);
  return { statements, error: null };
}

function identifierPattern() {
  return 'I(?:\\s*\\.\\s*I)?';
}

function balancedParentheses(value) {
  let depth = 0;
  for (const char of value) {
    if (char === '(') depth += 1;
    if (char === ')') depth -= 1;
    if (depth < 0) return false;
  }
  return depth === 0;
}

function classifyBaselineStatement(statement) {
  const identifier = identifierPattern();
  if (new RegExp(`^CREATE TYPE ${identifier} AS ENUM \\((?:\\s*S\\s*)(?:,\\s*S\\s*)*\\)$`, 'i').test(statement)) {
    return 'enum';
  }
  const tableMatch = statement.match(new RegExp(`^CREATE TABLE ${identifier} (\\([\\s\\S]*\\))$`, 'i'));
  if (tableMatch
    && balancedParentheses(tableMatch[1])
    && !/\b(?:SELECT|INSERT|UPDATE|DELETE|MERGE|COPY|TRUNCATE|DROP|GRANT|REVOKE|ALTER|CREATE|DO|CALL|EXECUTE)\b/i.test(tableMatch[1])) {
    return 'table';
  }
  const indexMatch = statement.match(new RegExp(`^CREATE (?:UNIQUE )?INDEX I ON ${identifier} (\\([\\s\\S]*\\))$`, 'i'));
  if (indexMatch
    && balancedParentheses(indexMatch[1])
    && !/\b(?:SELECT|INSERT|UPDATE|DELETE|MERGE|COPY|TRUNCATE|DROP|GRANT|REVOKE|ALTER|CREATE|DO|CALL|EXECUTE)\b/i.test(indexMatch[1])) {
    return 'index';
  }
  const action = '(?:CASCADE|RESTRICT|SET NULL|SET DEFAULT|NO ACTION)';
  const columns = '\\(\\s*I(?:\\s*,\\s*I)*\\s*\\)';
  const foreignKeyPattern = new RegExp(
    `^ALTER TABLE ${identifier} ADD CONSTRAINT I FOREIGN KEY ${columns} REFERENCES ${identifier} ${columns} ON DELETE ${action} ON UPDATE ${action}$`,
    'i',
  );
  if (foreignKeyPattern.test(statement)) return 'foreignKey';
  return null;
}

export function inspectBaselineSql(sql, errors, directory = '<baseline>') {
  const bytes = Buffer.byteLength(sql, 'utf8');
  if (bytes === 0 || bytes > MAX_BASELINE_SQL_BYTES || /_prisma_migrations/i.test(sql)) {
    errors.push({
      code: 'BASELINE_SQL_POLICY_VIOLATION',
      message: `${directory}/migration.sql viola tama\u00f1o, contenido o frontera _prisma_migrations.`,
    });
    return null;
  }
  const lexed = lexSqlStatements(sql);
  if (lexed.error || lexed.statements.length === 0 || lexed.statements.length > MAX_BASELINE_STATEMENTS) {
    errors.push({
      code: 'BASELINE_SQL_POLICY_VIOLATION',
      message: `${directory}/migration.sql no tiene una secuencia SQL can\u00f3nica y acotada.`,
    });
    return null;
  }
  const counts = { enum: 0, table: 0, index: 0, foreignKey: 0 };
  for (let index = 0; index < lexed.statements.length; index += 1) {
    const statement = lexed.statements[index];
    if (Buffer.byteLength(statement, 'utf8') > MAX_BASELINE_STATEMENT_BYTES) {
      errors.push({
        code: 'BASELINE_SQL_POLICY_VIOLATION',
        message: `${directory}/migration.sql contiene una sentencia fuera de presupuesto.`,
      });
      return null;
    }
    const kind = classifyBaselineStatement(statement);
    if (!kind) {
      errors.push({
        code: 'BASELINE_SQL_POLICY_VIOLATION',
        message: `${directory}/migration.sql contiene una sentencia no permitida en la posici\u00f3n ${index + 1}.`,
      });
      return null;
    }
    counts[kind] += 1;
  }
  if (counts.table === 0) {
    errors.push({
      code: 'BASELINE_SQL_POLICY_VIOLATION',
      message: `${directory}/migration.sql no crea ninguna tabla.`,
    });
    return null;
  }
  return { statementCount: lexed.statements.length, ...counts };
}

function collectMigrations(migrationsRoot, errors) {
  const allowedRootFiles = new Set(['migration_lock.toml', 'baseline-manifest.json']);
  const migrations = [];
  const entries = fs.readdirSync(migrationsRoot, { withFileTypes: true })
    .sort((left, right) => asciiCompare(left.name, right.name));

  for (const entry of entries) {
    const entryPath = path.join(migrationsRoot, entry.name);
    const stat = fs.lstatSync(entryPath);
    if (stat.isSymbolicLink()) {
      errors.push({ code: 'MIGRATION_SYMLINK', message: `No se permiten enlaces en prisma/migrations: ${entry.name}.` });
      continue;
    }
    if (entry.isFile()) {
      if (!allowedRootFiles.has(entry.name)) {
        errors.push({ code: 'MIGRATION_ROOT_EXTRA', message: `Archivo no gobernado en prisma/migrations: ${entry.name}.` });
      }
      continue;
    }
    if (!entry.isDirectory() || !MIGRATION_DIRECTORY_PATTERN.test(entry.name)) {
      errors.push({ code: 'MIGRATION_DIRECTORY_INVALID', message: `Directorio de migraci\u00f3n inv\u00e1lido: ${entry.name}.` });
      continue;
    }
    const children = fs.readdirSync(entryPath, { withFileTypes: true });
    if (children.length !== 1 || children[0].name !== 'migration.sql' || !children[0].isFile()) {
      errors.push({ code: 'MIGRATION_CONTENT_INVALID', message: `${entry.name} debe contener solamente migration.sql.` });
      continue;
    }
    const migrationPath = path.join(entryPath, 'migration.sql');
    const migrationStat = fs.lstatSync(migrationPath);
    if (migrationStat.isSymbolicLink()) {
      errors.push({ code: 'MIGRATION_FILE_INVALID', message: `${entry.name}/migration.sql debe ser un archivo regular.` });
      continue;
    }
    const sql = readCanonicalLfText(migrationPath, errors, 'MIGRATION_TEXT_NOT_CANONICAL');
    if (sql === null || sql.length === 0) continue;
    migrations.push({ directory: entry.name, sha256: sha256(sql), sql });
  }
  return migrations;
}

function computeHistorySha256(migrations) {
  return sha256(JSON.stringify(migrations.map(({ directory, sha256: digest }) => ({ directory, sha256: digest }))));
}

function computeBaselineId(provider, prismaMajor, baselineMigration) {
  return `prisma-baseline-${sha256(JSON.stringify({ provider, prismaMajor, baselineMigration }))}`;
}

function computeMigrationSetId(input) {
  return `prisma-set-${sha256(JSON.stringify(input))}`;
}

export function deriveBaselineManifest({ repoRoot }) {
  const errors = [];
  const prismaRoot = path.join(repoRoot, 'prisma');
  const schemaPath = path.join(prismaRoot, 'schema.prisma');
  const migrationsRoot = path.join(prismaRoot, 'migrations');
  const lockPath = path.join(migrationsRoot, 'migration_lock.toml');
  const toolchain = inspectPrismaToolchain(repoRoot, errors);

  if (!inspectRegularFile(schemaPath, errors, 'SCHEMA_MISSING')) {
    return { ok: false, errors };
  }
  const provider = inspectSchemaProvider(schemaPath, errors);
  if (!fs.existsSync(migrationsRoot)
    || !fs.lstatSync(migrationsRoot).isDirectory()
    || fs.lstatSync(migrationsRoot).isSymbolicLink()) {
    errors.push({ code: 'MIGRATIONS_MISSING', message: 'No existe una historia Prisma regular y revisada.' });
    return { ok: false, errors };
  }
  const lockText = readCanonicalLfText(lockPath, errors, 'MIGRATION_LOCK_MISSING');
  if (lockText !== null && lockText !== CANONICAL_MIGRATION_LOCK) {
    errors.push({ code: 'MIGRATION_LOCK_INVALID', message: 'migration_lock.toml no coincide byte a byte con el lock PostgreSQL can\u00f3nico.' });
  }
  const migrationsWithSql = collectMigrations(migrationsRoot, errors);
  if (migrationsWithSql.length === 0) {
    errors.push({ code: 'MIGRATIONS_EMPTY', message: 'La historia Prisma no contiene migration.sql aplicables.' });
  }
  const firstMigrationWithSql = migrationsWithSql[0] || null;
  if (firstMigrationWithSql && !BASELINE_DIRECTORY_PATTERN.test(firstMigrationWithSql.directory)) {
    errors.push({ code: 'BASELINE_DIRECTORY_INVALID', message: 'La primera migraci\u00f3n debe llamarse YYYYMMDDHHMMSS_baseline.' });
  }
  const baselineSql = firstMigrationWithSql
    ? inspectBaselineSql(firstMigrationWithSql.sql, errors, firstMigrationWithSql.directory)
    : null;
  if (!provider || !toolchain || lockText !== CANONICAL_MIGRATION_LOCK || !firstMigrationWithSql || !baselineSql) {
    return { ok: false, errors };
  }

  const migrations = migrationsWithSql.map(({ directory, sha256: digest }) => ({ directory, sha256: digest }));
  const baselineMigration = migrations[0];
  const schemaSha256 = normalizedFileSha256(schemaPath);
  const migrationHistorySha256 = computeHistorySha256(migrations);
  const migrationLockSha256 = sha256(lockText);
  const baselineId = computeBaselineId(provider, toolchain.prismaMajor, baselineMigration);
  const migrationSetInput = {
    contractVersion: 2,
    baselineId,
    schemaSha256,
    migrationLockSha256,
    baselinePolicyVersion: BASELINE_POLICY_VERSION,
    prismaVersion: toolchain.prismaVersion,
    prismaEngineVersion: toolchain.prismaEngineVersion,
    prismaToolchainLockSha256: toolchain.prismaToolchainLockSha256,
    migrationHistorySha256,
    migrations,
  };
  const migrationSetId = computeMigrationSetId(migrationSetInput);
  const manifest = {
    contractVersion: 2,
    provider,
    prismaMajor: toolchain.prismaMajor,
    prismaVersion: toolchain.prismaVersion,
    prismaEngineVersion: toolchain.prismaEngineVersion,
    prismaToolchainLockSha256: toolchain.prismaToolchainLockSha256,
    migrationLockSha256,
    baselinePolicyVersion: BASELINE_POLICY_VERSION,
    baselineId,
    baselineMigration,
    schemaSha256,
    migrationHistorySha256,
    migrationSetId,
    migrations,
  };
  return {
    ok: errors.length === 0,
    errors,
    manifest,
    schemaProvider: provider,
    schemaSha256,
    migrationHistorySha256,
    migrationLockSha256,
    baselineId,
    migrationSetId,
    migrations,
    baselineSql,
    toolchain,
  };
}

export function canonicalManifestText(manifest) {
  return `${JSON.stringify(manifest, null, 2)}\n`;
}
